  "content": "1|import { createInitialDesignerState } from '../../../domain/component-designer/state';
2|import type { DesignerNode, TemplateNodeSeed } from '../../../domain/component-designer/types';
3|import { SHELL_ROUTE_OUTLET_SLOT_ID } from '../../../shared/lib/shellRouteOutlet';
4|
5|/** Minimal portal layout: route outlet only (no chrome or navigation). */
6|export const COMPONENT_ALONE_LAYOUT_TEMPLATE: TemplateNodeSeed[] = [
7|  {
8|    type: 'container',
9|    props: { className: 'flex h-full min-h-0 w-full flex-col overflow-hidden bg-white' },
10|    children: [
11|      {
12|        type: 'system-slot',
13|        props: { slotId: SHELL_ROUTE_OUTLET_SLOT_ID, className: 'min-h-0 flex-1' },
14|      },
15|    ],
16|  },
17|];
18|
19|export function createStateFromComponentAloneLayoutTemplate(): {
20|  state: ReturnType<typeof createInitialDesignerState>;
21|  preferredSelectedNodeId: string | null;
22|} {
23|  const baseState = createInitialDesignerState();
24|  const rootNodeId = baseState.document.rootNodeId;
25|  const now = new Date().toISOString();
26|  const nodes: Record<string, DesignerNode> = {
27|    ...baseState.document.nodes,
28|  };
29|
30|  let seed = 0;
31|  const buildNode = (item: TemplateNodeSeed, parentId: string, order: number): string => {
32|    seed += 1;
33|    const nodeId = `component-alone-${item.type}-${Date.now()}-${seed}`;
34|    const children = (item.children ?? []).map((child, childIndex) => buildNode(child, nodeId, childIndex));
35|
36|    nodes[nodeId] = {
37|      id: nodeId,
38|      type: item.type,
39|      parentId,
40|      order,
41|      props: { ...(item.props ?? {}) },
42|      layout: {},
43|      binding: {},
44|      children,
45|    };
46|
47|    return nodeId;
48|  };
49|
50|  const rootChildren = COMPONENT_ALONE_LAYOUT_TEMPLATE.map((item, index) => buildNode(item, rootNodeId, index));
51|  nodes[rootNodeId] = {
52|    ...nodes[rootNodeId],
53|    children: rootChildren,
54|  };
55|
56|  return {
57|    state: {
58|      ...baseState,
59|      document: {
60|        ...baseState.document,
61|        nodes,
62|        metadata: {
63|          ...baseState.document.metadata,
64|          updatedAt: now,
65|        },
66|      },
67|    },
68|    preferredSelectedNodeId: rootChildren[0] ?? null,
69|  };
70|}
